import{_ as n,o as i,c as o,a0 as a}from"./chunks/framework.Ckbw5VQO.js";const t="/geo-ml/documentation/learning/deep-learning/cnn/04_convolution.png",l="/geo-ml/documentation/learning/deep-learning/cnn/05_cnn.png",r="/geo-ml/documentation/learning/deep-learning/cnn/06_cnn.png",s="/geo-ml/documentation/learning/deep-learning/cnn/07_cnn.png",u="/geo-ml/documentation/learning/deep-learning/cnn/08_cnn.png",c="/geo-ml/documentation/learning/deep-learning/cnn/10_cnn.png",d="/geo-ml/documentation/learning/deep-learning/cnn/11_cnn.png",g="/geo-ml/documentation/learning/deep-learning/cnn/13_cnn.png",m="/geo-ml/documentation/learning/deep-learning/cnn/14_cnn.png",p="/geo-ml/documentation/learning/deep-learning/cnn/15_cnn.png",h="/geo-ml/documentation/learning/deep-learning/cnn/12_cnn.png",v="/geo-ml/documentation/learning/deep-learning/cnn/16_cnn.png",_="/geo-ml/documentation/learning/deep-learning/cnn/17_cnn.png",f="/geo-ml/documentation/learning/deep-learning/cnn/18_cnn.png",S=JSON.parse(`{"title":"Principe de convolution d'images","description":"","frontmatter":{},"headers":[],"relativePath":"fr/learning/deep-learning/cnn/principle.md","filePath":"fr/learning/deep-learning/cnn/principle.md"}`),y={name:"fr/learning/deep-learning/cnn/principle.md"};function b(x,e,q,k,P,w){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="principe-de-convolution-d-images" tabindex="-1">Principe de convolution d&#39;images <a class="header-anchor" href="#principe-de-convolution-d-images" aria-label="Permalink to &quot;Principe de convolution d&#39;images&quot;">​</a></h1><p>Un filtre (ou <em>kernel</em>, ou <em>noyau</em>) est une petite matrice de poids. On le fait glisser sur l&#39;image : à chaque position, on multiplie les valeurs du filtre par les pixels sous-jacents et on additionne. Le résultat est un pixel dans la <strong>carte d&#39;activation</strong> (<em>feature map</em>).</p><img src="'+t+'" style="display:block;margin:0 auto;width:100%;height:auto;"><div class="tip custom-block"><p class="custom-block-title">Terminologie</p><ul><li><strong>filtre / noyau / kernel</strong> = la matrice de poids (3×3 ici).</li><li><strong>convolution</strong> = l&#39;opération de glissement + multiplication + somme.</li><li><strong>Couche de convolution</strong> = un <strong>ensemble de N filtres</strong> appliqués en parallèle à la même entrée. Sortie : N feature maps empilées.</li><li><strong>feature map</strong> = l&#39;image de sortie produite par un filtre donné.</li></ul></div><details class="details custom-block"><summary>Glissement de la fenêtre</summary><p>L&#39;animation ci-dessous montre concrètement comment le noyau parcourt l&#39;image, pixel par pixel.</p><div style="display:flex;gap:2rem;"><div style="flex:1;"><img src="'+l+'" style="display:block;margin:0 auto;width:100%;height:auto;"></div><div style="flex:1;"><img src="'+r+'" style="display:block;margin:0 auto;width:100%;height:auto;"></div></div></details><h2 id="_2d-convolution-image-en-niveaux-de-gris" tabindex="-1">2D convolution : image en niveaux de gris <a class="header-anchor" href="#_2d-convolution-image-en-niveaux-de-gris" aria-label="Permalink to &quot;2D convolution : image en niveaux de gris&quot;">​</a></h2><h3 id="appliquer-le-filtre-sur-l-image" tabindex="-1">Appliquer le filtre sur l&#39;image <a class="header-anchor" href="#appliquer-le-filtre-sur-l-image" aria-label="Permalink to &quot;Appliquer le filtre sur l&#39;image&quot;">​</a></h3><img src="'+s+'" style="display:block;margin:0 auto;width:100%;height:auto;"><img src="'+u+'" style="display:block;margin:0 auto;width:100%;height:auto;"><h3 id="couches-de-convolutions-conv2d" tabindex="-1">Couches de convolutions <code>Conv2d</code> <a class="header-anchor" href="#couches-de-convolutions-conv2d" aria-label="Permalink to &quot;Couches de convolutions `Conv2d`&quot;">​</a></h3><img src="'+c+'" style="display:block;margin:0 auto;width:100%;height:auto;"><h2 id="_3d-convolution-image-en-couleur" tabindex="-1">3D convolution : image en couleur <a class="header-anchor" href="#_3d-convolution-image-en-couleur" aria-label="Permalink to &quot;3D convolution : image en couleur&quot;">​</a></h2><h3 id="appliquer-le-filtre-sur-l-image-1" tabindex="-1">Appliquer le filtre sur l&#39;image <a class="header-anchor" href="#appliquer-le-filtre-sur-l-image-1" aria-label="Permalink to &quot;Appliquer le filtre sur l&#39;image&quot;">​</a></h3><img src="'+d+'" style="display:block;margin:0 auto;width:100%;height:auto;"><details class="details custom-block"><summary>RGB</summary><p>Une image en couleur a trois canaux R, G, B. <img src="'+g+'" style="display:block;margin:0 auto;width:50%;height:auto;"> Pour la convolution, le filtre doit pouvoir voir les trois canaux à la fois, il devient donc lui aussi un volume 3D. <img src="'+m+'" style="display:block;margin:0 auto;width:50%;height:auto;"> Concrètement, un noyau 3×3 sur une image RGB n&#39;est pas une matrice 3×3, c&#39;est un volume 3×3×3 : un sous-noyau 3×3 par canal, dont les sorties sont <strong>sommées</strong> pour produire un seul pixel de feature map. <img src="'+p+'" style="display:block;margin:0 auto;width:50%;height:auto;"></p></details><h3 id="couches-de-convolutions-conv2d-1" tabindex="-1">Couches de convolutions <code>Conv2d</code> <a class="header-anchor" href="#couches-de-convolutions-conv2d-1" aria-label="Permalink to &quot;Couches de convolutions `Conv2d`&quot;">​</a></h3><img src="'+h+'" style="display:block;margin:0 auto;width:100%;height:auto;"><h2 id="parametres" tabindex="-1">Paramètres <a class="header-anchor" href="#parametres" aria-label="Permalink to &quot;Paramètres&quot;">​</a></h2><h3 id="padding" tabindex="-1">Padding <a class="header-anchor" href="#padding" aria-label="Permalink to &quot;Padding&quot;">​</a></h3><p>Quand le noyau arrive au bord de l&#39;image, une partie de la fenêtre <strong>tombe dans le vide</strong>. On a deux conséquences :</p><ol><li>La feature map est <strong>plus petite</strong> que l&#39;image d&#39;entrée.</li><li>Les pixels du bord sont <strong>sous-représentés</strong>, chaque pixel intérieur participe à 9 calculs (pour un 3×3), un pixel de coin n&#39;en voit qu&#39;<strong>un seul</strong>.</li></ol><div style="display:flex;gap:2rem;"><div style="flex:1;"><img src="'+v+'" style="display:block;margin:0 auto;width:100%;height:auto;"></div><div style="flex:1;"><img src="'+_+'" style="display:block;margin:0 auto;width:100%;height:auto;"></div></div><p><strong>Solution : le padding</strong> : On ajoute des <strong>pixels fictifs</strong> autour de l&#39;image avant la convolution. Le plus simple est le <em>zero-padding</em> (on remplit avec des 0) ; on trouve aussi le <em>reflect</em> (miroir) ou le <em>replicate</em> (copie du bord). <img src="'+f+'" style="display:block;margin:0 auto;width:50%;height:auto;"></p><h3 id="strides-le-pas" tabindex="-1">Strides (Le pas) <a class="header-anchor" href="#strides-le-pas" aria-label="Permalink to &quot;Strides (Le pas)&quot;">​</a></h3><p>Au lieu de glisser le noyau d&#39;<strong>un pixel</strong>, on peut le faire glisser de 2, 3, n. C&#39;est le <strong>stride</strong>. Effet : la feature map est sous-échantillonnée, la sortie devient plus petite que l&#39;entrée d&#39;un facteur égal au stride.</p>',25)])])}const A=n(y,[["render",b]]);export{S as __pageData,A as default};
